"""Date parsing for invoice imports."""

import re

try:
    from shared.utils import split_date  # platform helper, present in full checkouts
except ImportError:
    def split_date(text):
        """Split a 'YYYY-MM-DD' string into year, month and day strings."""
        year, month, day = text.strip().split("-")
        return year, month, day


_YEAR_FIRST = re.compile(r"^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$")
_DAY_FIRST = re.compile(r"^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$")


def parse_date(text):
    """Parse an import date into a (year, month, day) tuple of ints.

    Supported formats: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD (year first) and
    DD.MM.YYYY, DD/MM/YYYY, DD-MM-YYYY (day first).
    """
    s = text.strip()
    m = _YEAR_FIRST.match(s)
    if m:
        year, month, day = m.groups()
    else:
        m = _DAY_FIRST.match(s)
        if m:
            day, month, year = m.groups()
        else:
            year, month, day = split_date(s)
    year, month, day = int(year), int(month), int(day)
    if not (1 <= month <= 12 and 1 <= day <= 31):
        raise ValueError(f"invalid date: {text!r}")
    return (year, month, day)

